// ─────────────────────────────────────────────────────────────────────────────
// Load & Normalize Domain List
// Sources: the embedded fixture (SANDBOX_MODE=true, identical to
// sample-payloads/domains-list.json), SENDER_DOMAINS (comma list or JSON), or
// the JSON fetched by "HTTP: Fetch Domain List" (DOMAIN_SOURCE=url).
// Validates hostnames, lower-cases, de-duplicates, drops disabled entries and
// applies per-domain defaults.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const FIXTURE = {
  "_comment": "Synthetic fixture. All domains use reserved example TLDs. Shape documented in README \u00a78.2.",
  "domains": [
    {
      "domain": "sender.example.com",
      "role": "sending_domain_web",
      "owner": "team-deliverability",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "mail.example.com",
      "role": "webmail",
      "owner": "team-it",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "track.example.com",
      "role": "click_tracking",
      "owner": "team-marketing-ops",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "links.example.net",
      "role": "link_branding",
      "owner": "team-marketing-ops",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "go.example.org",
      "role": "landing_pages",
      "owner": "team-web",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "bounce.example.com",
      "role": "smtp_implicit_tls",
      "owner": "team-deliverability",
      "port": 465,
      "checkHeaders": false,
      "checkRedirect": false
    },
    {
      "domain": "legacy.example.com",
      "role": "legacy_preference_center",
      "owner": "team-web",
      "port": 443,
      "path": "/preferences",
      "checkHeaders": true
    },
    {
      "domain": "promo.example.com",
      "role": "campaign_microsite",
      "owner": "team-marketing-ops",
      "port": 443,
      "path": "/",
      "checkHeaders": true
    },
    {
      "domain": "archive.example.com",
      "role": "retired_microsite",
      "owner": "team-web",
      "enabled": false
    },
    {
      "domain": "not a domain!",
      "role": "invalid_entry_for_testing"
    },
    {
      "domain": "SENDER.example.com",
      "role": "duplicate_entry_for_testing"
    }
  ]
};

let raw = [];
let source = 'fixture';
if (cfg.sandboxMode) {
  raw = FIXTURE.domains;
} else if (cfg.domainSource === 'url') {
  source = 'url';
  let fetched = null;
  try { fetched = $('HTTP: Fetch Domain List').first().json; } catch (e) { fetched = null; }
  if (!fetched || fetched.error) throw new Error('DOMAIN_SOURCE=url but the domain list could not be fetched. Check DOMAINS_LIST_URL.');
  raw = Array.isArray(fetched) ? fetched : (fetched.domains || fetched.data || []);
} else {
  source = 'env';
  const txt = String(cfg.senderDomainsRaw || '').trim();
  if (txt.startsWith('[') || txt.startsWith('{')) {
    try { const j = JSON.parse(txt); raw = Array.isArray(j) ? j : (j.domains || []); }
    catch (e) { throw new Error('SENDER_DOMAINS looks like JSON but does not parse.'); }
  } else {
    raw = txt.split(/[\s,;]+/).filter(Boolean);
  }
}

const HOST = /^(?=.{1,253}$)(?!-)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const seen = new Set();
const domains = [];
const rejected = [];
for (const entry of raw) {
  const e = typeof entry === 'string' ? { domain: entry } : (entry || {});
  const domain = String(e.domain || e.host || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/[/:].*$/, '').replace(/\.$/, '');
  if (e.enabled === false) { rejected.push({ domain: domain || null, reason: 'disabled' }); continue; }
  if (!HOST.test(domain) && !(cfg.allowPrivateTargets && domain === 'localhost')) { rejected.push({ domain: String(e.domain || '').slice(0, 80), reason: 'invalid_hostname' }); continue; }
  const port = Number.isInteger(Number(e.port)) && Number(e.port) > 0 && Number(e.port) < 65536 ? Number(e.port) : 443;
  const key = `${domain}:${port}`;
  if (seen.has(key)) { rejected.push({ domain, reason: 'duplicate' }); continue; }
  seen.add(key);
  if (domains.length >= cfg.maxDomains) { rejected.push({ domain, reason: 'over_max_domains' }); continue; }
  const checkHeaders = e.checkHeaders === undefined ? port === 443 : Boolean(e.checkHeaders);
  domains.push({
    domain, port,
    path: typeof e.path === 'string' && e.path.startsWith('/') ? e.path.slice(0, 200) : '/',
    role: String(e.role || 'unspecified').slice(0, 60),
    owner: String(e.owner || '').slice(0, 80) || null,
    checkHeaders,
    checkRedirect: e.checkRedirect === undefined ? (checkHeaders && cfg.checkHttpRedirect) : Boolean(e.checkRedirect) && cfg.checkHttpRedirect,
    requiredHeaders: Array.isArray(e.requiredHeaders) ? e.requiredHeaders.map((h) => String(h).toLowerCase()) : null,
    warningDays: Number.isFinite(Number(e.warningDays)) ? Number(e.warningDays) : null,
  });
}
return [{ json: { source, domains, rejected, count: domains.length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Mock Inspection Results (SANDBOX_MODE=true)
// Synthetic observations in exactly the shape the live inspector produces,
// dated relative to "now" so every scenario stays stable over time.
// No DNS, TLS or HTTP traffic is generated.
// ─────────────────────────────────────────────────────────────────────────────
const { domains } = $('Load & Normalize Domain List').first().json;
const DAY = 86400000;
const at = (days) => new Date(Date.now() + days * DAY).toISOString();
const GOOD_HEADERS = {
  'strict-transport-security': 'max-age=31536000; includeSubDomains; preload',
  'content-security-policy': "default-src 'self'; frame-ancestors 'none'",
  'x-frame-options': 'DENY',
  'x-content-type-options': 'nosniff',
  'referrer-policy': 'strict-origin-when-cross-origin',
};
const tlsOk = (host, days, extra = {}) => ({
  authorized: true, authorizationError: null, identityError: null, protocol: 'TLSv1.3', cipher: 'TLS_AES_256_GCM_SHA384',
  cert: { subjectCN: host, subjectAltNames: [host], issuer: 'Synthetic Issuing CA R1', validFrom: at(Math.min(-10, days - 90)), validTo: at(days + 0.5), serialNumber: '0A1B2C3D4E5F', fingerprint256: 'AA:BB:CC:DD:00:11:22:33', bits: 256, keyType: 'EC', selfSigned: false },
  chain: [{ subject: 'Synthetic Issuing CA R1', issuer: 'Synthetic Root CA X1', validTo: at(900) }, { subject: 'Synthetic Root CA X1', issuer: 'Synthetic Root CA X1', validTo: at(3000) }],
  ...extra,
});
const page = (host, headers, path = '/') => ({ status: 200, headers, hops: [{ url: `https://${host}${path}`, status: 200, location: null }], firstHsts: headers['strict-transport-security'] || null, finalUrl: `https://${host}${path}` });
const redirectOk = (host) => ({ status: 301, location: `https://${host}/`, redirectsToHttps: true });

const SCENARIOS = {
  'sender.example.com': (d) => ({ resolvedIp: '192.0.2.10', tls: tlsOk(d.domain, 74), https: page(d.domain, GOOD_HEADERS), http: redirectOk(d.domain) }),
  'mail.example.com': (d) => {
    const h = { ...GOOD_HEADERS }; delete h['content-security-policy'];
    return { resolvedIp: '192.0.2.11', tls: tlsOk(d.domain, 21), https: page(d.domain, h), http: redirectOk(d.domain) };
  },
  'track.example.com': (d) => ({
    resolvedIp: '192.0.2.12', tls: tlsOk(d.domain, 5),
    https: { status: 404, headers: { 'x-content-type-options': 'nosniff' }, hops: [{ url: `https://${d.domain}/`, status: 302, location: `https://${d.domain}/c/landing` }, { url: `https://${d.domain}/c/landing`, status: 404, location: null }], firstHsts: null, finalUrl: `https://${d.domain}/c/landing` },
    http: { status: 200, location: null, redirectsToHttps: false },
  }),
  'links.example.net': (d) => ({ resolvedIp: '198.51.100.20', tls: tlsOk(d.domain, -3, { authorized: false, authorizationError: 'CERT_HAS_EXPIRED' }), https: page(d.domain, GOOD_HEADERS), http: redirectOk(d.domain) }),
  'go.example.org': (d) => {
    const t = tlsOk('*.cdn.example.net', 200, { authorized: true, identityError: "Host: go.example.org. is not in the cert's altnames: DNS:*.cdn.example.net" });
    t.cert.subjectAltNames = ['*.cdn.example.net', 'cdn.example.net'];
    return { resolvedIp: '198.51.100.21', tls: t, https: page(d.domain, { ...GOOD_HEADERS, 'strict-transport-security': 'max-age=86400' }), http: redirectOk(d.domain) };
  },
  'bounce.example.com': (d) => ({ resolvedIp: '192.0.2.15', tls: tlsOk(d.domain, 120, { protocol: 'TLSv1.2', cipher: 'ECDHE-RSA-AES256-GCM-SHA384' }), https: null, http: null }),
  'legacy.example.com': (d) => {
    const t = tlsOk(d.domain, 400, { authorized: false, authorizationError: 'DEPTH_ZERO_SELF_SIGNED_CERT', protocol: 'TLSv1.1', cipher: 'AES128-SHA' });
    t.cert.issuer = d.domain; t.cert.selfSigned = true; t.cert.bits = 1024; t.cert.keyType = 'RSA'; t.chain = [];
    return { resolvedIp: '192.0.2.16', tls: t, https: page(d.domain, { server: 'synthetic-httpd/2.2' }, d.path), http: { status: 200, location: null, redirectsToHttps: false } };
  },
  'promo.example.com': () => ({ error: { stage: 'dns', code: 'ENOTFOUND', message: 'DNS lookup failed (ENOTFOUND).' } }),
};

const observations = domains.map((d) => {
  const base = { domain: d.domain, port: d.port, path: d.path, role: d.role, owner: d.owner, checkHeaders: d.checkHeaders, checkRedirect: d.checkRedirect, requiredHeaders: d.requiredHeaders, warningDays: d.warningDays, inspectedAt: new Date().toISOString(), resolvedIp: null, error: null, tls: null, https: null, http: null };
  const s = SCENARIOS[d.domain] ? SCENARIOS[d.domain](d) : { resolvedIp: '192.0.2.99', tls: tlsOk(d.domain, 60), https: d.checkHeaders ? page(d.domain, GOOD_HEADERS) : null, http: d.checkRedirect ? redirectOk(d.domain) : null };
  const o = { ...base, ...s };
  if (!d.checkHeaders) o.https = null;
  if (!d.checkRedirect) o.http = null;
  return o;
});
return [{ json: { mode: 'mock', durationMs: 0, observations } }];

// ─────────────────────────────────────────────────────────────────────────────
// Security Inspection (TLS + Headers)  ·  live path only (SANDBOX_MODE=false)
// Uses Node.js built-ins only: dns, tls, https, http.
// Per domain:
//   1. DNS lookup + SSRF guard (private/loopback/link-local targets refused
//      unless ALLOW_PRIVATE_TARGETS=true).
//   2. TLS handshake with SNI → certificate, chain, trust result, hostname
//      check, protocol, cipher, key size.
//   3. HTTPS GET (optional) → status, security headers, redirect chain.
//   4. HTTP GET on port 80 (optional) → is there a redirect to HTTPS?
// Connections go to the resolved, vetted IP with SNI/Host set to the domain,
// so DNS can't be re-pointed between the check and the connection.
// Records raw observations only; "Evaluate Findings" decides severity.
// Requires NODE_FUNCTION_ALLOW_BUILTIN to include dns,tls,https,http.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { domains } = $('Load & Normalize Domain List').first().json;

let dns, tls, https, http, net;
try {
  dns = require('dns'); tls = require('tls'); https = require('https'); http = require('http'); net = require('net');
} catch (e) {
  throw new Error('Security inspection needs NODE_FUNCTION_ALLOW_BUILTIN=dns,tls,https,http,net (see README §4).');
}

const HEADERS = ['strict-transport-security', 'content-security-policy', 'x-frame-options', 'x-content-type-options', 'referrer-policy', 'permissions-policy', 'server'];

function isPrivate(ip) {
  if (net.isIPv4(ip)) {
    const [a, b] = ip.split('.').map(Number);
    return a === 10 || a === 127 || a === 0 || (a === 169 && b === 254) || (a === 172 && b >= 16 && b <= 31) || (a === 192 && b === 168) || (a === 100 && b >= 64 && b <= 127) || a >= 224;
  }
  const v = ip.toLowerCase();
  if (v.startsWith('::ffff:')) return isPrivate(v.slice(7));
  return v === '::1' || v === '::' || v.startsWith('fc') || v.startsWith('fd') || v.startsWith('fe80') || v.startsWith('ff');
}

function resolve(host) {
  return new Promise((ok) => {
    dns.lookup(host, { all: false }, (err, address) => ok(err ? { error: err.code || 'DNS_ERROR' } : { ip: address }));
  });
}

function vetTarget(host, ip) {
  if (!cfg.allowPrivateTargets && isPrivate(ip)) return { stage: 'policy', code: 'PRIVATE_TARGET_BLOCKED', message: `${host} resolves to a private or reserved address; set ALLOW_PRIVATE_TARGETS=true to inspect internal hosts.` };
  return null;
}

const iso = (d) => { const t = Date.parse(d); return Number.isFinite(t) ? new Date(t).toISOString() : null; };
const cn = (o) => (o && (o.CN || o.O)) || null;

function tlsProbe(host, ip, port) {
  return new Promise((ok) => {
    let done = false;
    const finish = (v, s) => { if (done) return; done = true; try { s && s.destroy(); } catch (e) { /* ignore */ } ok(v); };
    const socket = tls.connect({ host: ip, port, servername: net.isIP(host) ? undefined : host, rejectUnauthorized: false, timeout: cfg.timeoutMs, ALPNProtocols: ['http/1.1'] }, () => {
      const cert = socket.getPeerCertificate(true) || {};
      if (!cert || !cert.valid_to) return finish({ error: { stage: 'tls', code: 'NO_CERTIFICATE', message: 'Server presented no certificate.' } }, socket);
      const idErr = tls.checkServerIdentity(host, cert);
      const chain = [];
      let c = cert.issuerCertificate;
      const seenFp = new Set([cert.fingerprint256]);
      while (c && c.fingerprint256 && !seenFp.has(c.fingerprint256) && chain.length < 6) {
        seenFp.add(c.fingerprint256);
        chain.push({ subject: cn(c.subject), issuer: cn(c.issuer), validTo: iso(c.valid_to) });
        c = c.issuerCertificate;
      }
      const cipher = socket.getCipher() || {};
      finish({
        tls: {
          authorized: socket.authorized === true,
          authorizationError: socket.authorizationError ? String(socket.authorizationError) : null,
          identityError: idErr ? String(idErr.reason || idErr.message) : null,
          protocol: socket.getProtocol(),
          cipher: cipher.name || null,
          cert: {
            subjectCN: cn(cert.subject),
            subjectAltNames: String(cert.subjectaltname || '').split(',').map((s) => s.trim().replace(/^DNS:/, '')).filter(Boolean).slice(0, 50),
            issuer: cn(cert.issuer),
            validFrom: iso(cert.valid_from),
            validTo: iso(cert.valid_to),
            serialNumber: cert.serialNumber || null,
            fingerprint256: cert.fingerprint256 || null,
            bits: cert.bits || null,
            keyType: cert.asn1Curve || cert.nistCurve ? 'EC' : (cert.bits ? 'RSA' : null),
            selfSigned: Boolean(cert.fingerprint256 && cert.issuerCertificate && cert.issuerCertificate.fingerprint256 === cert.fingerprint256),
          },
          chain,
        },
      }, socket);
    });
    socket.on('timeout', () => finish({ error: { stage: 'tls', code: 'TIMEOUT', message: `TLS handshake exceeded ${cfg.timeoutMs} ms.` } }, socket));
    socket.on('error', (e) => finish({ error: { stage: 'tls', code: e.code || 'TLS_ERROR', message: String(e.message).slice(0, 200) } }, socket));
  });
}

function request(mod, opts) {
  return new Promise((ok) => {
    let done = false;
    const finish = (v) => { if (!done) { done = true; ok(v); } };
    const req = mod.request(opts, (res) => {
      const headers = {};
      for (const h of HEADERS) if (res.headers[h] !== undefined) headers[h] = String(res.headers[h]).slice(0, 1000);
      finish({ status: res.statusCode, headers, location: res.headers.location ? String(res.headers.location).slice(0, 500) : null });
      res.destroy();
    });
    req.on('timeout', () => { req.destroy(); finish({ error: 'TIMEOUT' }); });
    req.on('error', (e) => finish({ error: e.code || 'REQUEST_ERROR' }));
    req.end();
  });
}

async function httpsProbe(host, ip, port, path) {
  const hops = [];
  let curHost = host; let curIp = ip; let curPort = port; let curPath = path;
  let firstHsts = null;
  for (let i = 0; i <= cfg.maxRedirects; i += 1) {
    const r = await request(https, { host: curIp, port: curPort, path: curPath, method: 'GET', servername: net.isIP(curHost) ? undefined : curHost, rejectUnauthorized: false, timeout: cfg.timeoutMs, headers: { Host: curPort === 443 ? curHost : `${curHost}:${curPort}`, 'User-Agent': cfg.userAgent, Accept: 'text/html,*/*' } });
    if (r.error) return { error: r.error, hops };
    hops.push({ url: `https://${curHost}${curPort === 443 ? '' : `:${curPort}`}${curPath}`, status: r.status, location: r.location });
    if (firstHsts === null && r.headers['strict-transport-security']) firstHsts = r.headers['strict-transport-security'];
    if (r.status >= 300 && r.status < 400 && r.location) {
      let next;
      try { next = new URL(r.location, `https://${curHost}${curPath}`); } catch (e) { return { status: r.status, headers: r.headers, hops, firstHsts, redirectError: 'INVALID_LOCATION' }; }
      if (next.protocol !== 'https:') return { status: r.status, headers: r.headers, hops, firstHsts, redirectError: 'REDIRECT_TO_HTTP' };
      if (i === cfg.maxRedirects) return { status: r.status, headers: r.headers, hops, firstHsts, redirectError: 'TOO_MANY_REDIRECTS' };
      const res = await resolve(next.hostname);
      if (res.error) return { status: r.status, headers: r.headers, hops, firstHsts, redirectError: `REDIRECT_DNS_${res.error}` };
      if (vetTarget(next.hostname, res.ip)) return { status: r.status, headers: r.headers, hops, firstHsts, redirectError: 'REDIRECT_TO_PRIVATE_TARGET' };
      curHost = next.hostname; curIp = res.ip; curPort = Number(next.port) || 443; curPath = `${next.pathname}${next.search}`;
      continue;
    }
    return { status: r.status, headers: r.headers, hops, firstHsts, finalUrl: hops[hops.length - 1].url };
  }
  return { error: 'TOO_MANY_REDIRECTS', hops };
}

async function inspect(d) {
  const obs = { domain: d.domain, port: d.port, path: d.path, role: d.role, owner: d.owner, checkHeaders: d.checkHeaders, checkRedirect: d.checkRedirect, requiredHeaders: d.requiredHeaders, warningDays: d.warningDays, inspectedAt: new Date().toISOString(), resolvedIp: null, error: null, tls: null, https: null, http: null };
  const r = await resolve(d.domain);
  if (r.error) { obs.error = { stage: 'dns', code: r.error, message: `DNS lookup failed (${r.error}).` }; return obs; }
  obs.resolvedIp = r.ip;
  const blocked = vetTarget(d.domain, r.ip);
  if (blocked) { obs.error = blocked; return obs; }
  const t = await tlsProbe(d.domain, r.ip, d.port);
  if (t.error) { obs.error = t.error; return obs; }
  obs.tls = t.tls;
  if (d.checkHeaders) obs.https = await httpsProbe(d.domain, r.ip, d.port, d.path);
  if (d.checkRedirect) {
    const h = await request(http, { host: r.ip, port: 80, path: '/', method: 'GET', timeout: cfg.timeoutMs, headers: { Host: d.domain, 'User-Agent': cfg.userAgent } });
    obs.http = h.error ? { error: h.error } : { status: h.status, location: h.location, redirectsToHttps: h.status >= 300 && h.status < 400 && /^https:\/\//i.test(String(h.location || '')) };
  }
  return obs;
}

// Bounded concurrency
const observations = new Array(domains.length);
let next = 0;
const worker = async () => { while (next < domains.length) { const i = next; next += 1; observations[i] = await inspect(domains[i]); } };
const started = Date.now();
await Promise.all(Array.from({ length: Math.min(cfg.concurrency, domains.length) }, worker));
return [{ json: { mode: 'live', durationMs: Date.now() - started, observations } }];

// ─────────────────────────────────────────────────────────────────────────────
// Evaluate Findings
// Turns raw observations into findings with a severity:
//   critical: unreachable, expired, not yet valid, untrusted chain, hostname
//             mismatch, ≤ CRITICAL_DAYS to expiry
//   warning:  ≤ DAYS_WARNING_THRESHOLD to expiry, intermediate expiring,
//             TLS < 1.2, weak key, missing/weak security headers (severity
//             set by HEADER_SEVERITY), no HTTP→HTTPS redirect
//   info:     optional headers absent, Server header discloses a version
// A domain's status is its worst finding (ok when none).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const { observations, mode, durationMs } = $input.first().json;
const DAY = 86400000;
const RANK = { ok: 0, info: 1, warning: 2, critical: 3 };
const now = Date.now();
const days = (iso) => (iso ? Math.floor((Date.parse(iso) - now) / DAY) : null);

const results = observations.map((o) => {
  const f = [];
  const add = (severity, code, message) => f.push({ severity, code, message });
  const warnDays = o.warningDays ?? cfg.daysWarningThreshold;
  let daysRemaining = null;

  if (o.error) {
    const sev = o.error.code === 'PRIVATE_TARGET_BLOCKED' ? 'warning' : 'critical';
    add(sev, `${o.error.stage}_${String(o.error.code).toLowerCase()}`, o.error.message || o.error.code);
  }
  const t = o.tls;
  if (t) {
    daysRemaining = days(t.cert.validTo);
    const notBefore = t.cert.validFrom ? Date.parse(t.cert.validFrom) : null;
    if (daysRemaining !== null && Date.parse(t.cert.validTo) <= now) add('critical', 'cert_expired', `Certificate expired ${Math.abs(daysRemaining)} day(s) ago (${t.cert.validTo.slice(0, 10)}).`);
    else if (notBefore && notBefore > now) add('critical', 'cert_not_yet_valid', `Certificate is not valid before ${t.cert.validFrom.slice(0, 10)}.`);
    else if (daysRemaining !== null && daysRemaining <= cfg.criticalDays) add('critical', 'cert_expiring_critical', `Certificate expires in ${daysRemaining} day(s) (${t.cert.validTo.slice(0, 10)}).`);
    else if (daysRemaining !== null && daysRemaining <= warnDays) add('warning', 'cert_expiring_soon', `Certificate expires in ${daysRemaining} day(s) (${t.cert.validTo.slice(0, 10)}).`);

    if (t.identityError) add('critical', 'hostname_mismatch', `Certificate does not cover ${o.domain} (SANs: ${t.cert.subjectAltNames.slice(0, 5).join(', ') || 'none'}).`);
    if (!t.authorized && t.authorizationError && t.authorizationError !== 'CERT_HAS_EXPIRED') {
      add('critical', 'chain_untrusted', `Certificate chain is not trusted (${t.authorizationError}${t.cert.selfSigned ? ', self-signed' : ''}).`);
    }
    for (const c of t.chain || []) {
      const d = days(c.validTo);
      if (c.subject !== c.issuer && d !== null && d <= warnDays) add('warning', 'intermediate_expiring', `Intermediate "${c.subject}" expires in ${d} day(s).`);
    }
    if (t.protocol && !['TLSv1.2', 'TLSv1.3'].includes(t.protocol)) add('warning', 'weak_tls_protocol', `Negotiated ${t.protocol}; require TLS 1.2 or later.`);
    if (t.cert.keyType === 'RSA' && t.cert.bits && t.cert.bits < 2048) add('warning', 'weak_key', `RSA key is ${t.cert.bits} bits; use 2048 or more.`);
  }

  const h = o.https;
  if (o.checkHeaders && h) {
    if (h.error) add(cfg.headerSeverity === 'info' ? 'warning' : cfg.headerSeverity, 'https_request_failed', `HTTPS request failed (${h.error}).`);
    else {
      if (h.redirectError) add('warning', `redirect_${h.redirectError.toLowerCase()}`, `HTTPS redirect chain problem: ${h.redirectError}.`);
      const hd = h.headers || {};
      const required = o.requiredHeaders || cfg.requiredHeaders;
      const hsts = h.firstHsts || hd['strict-transport-security'] || null;
      for (const name of required) {
        if (name === 'strict-transport-security') {
          if (!hsts) add(cfg.headerSeverity, 'header_missing_hsts', 'Strict-Transport-Security header is missing.');
          else {
            const m = /max-age\s*=\s*"?(\d+)/i.exec(hsts);
            const age = m ? Number(m[1]) : 0;
            if (age < cfg.hstsMinMaxAge) add(cfg.headerSeverity, 'header_weak_hsts', `HSTS max-age is ${age}s; minimum is ${cfg.hstsMinMaxAge}s.`);
          }
        } else if (name === 'x-frame-options') {
          const csp = String(hd['content-security-policy'] || '');
          if (!hd['x-frame-options'] && !/frame-ancestors/i.test(csp)) add(cfg.headerSeverity, 'header_missing_x_frame_options', 'Neither X-Frame-Options nor CSP frame-ancestors is set.');
        } else if (name === 'x-content-type-options') {
          if (String(hd['x-content-type-options'] || '').toLowerCase() !== 'nosniff') add(cfg.headerSeverity, 'header_missing_x_content_type_options', 'X-Content-Type-Options: nosniff is missing.');
        } else if (!hd[name]) {
          add(cfg.headerSeverity, `header_missing_${name.replace(/-/g, '_')}`, `${name} header is missing.`);
        }
      }
      if (!required.includes('referrer-policy') && !hd['referrer-policy']) add('info', 'header_absent_referrer_policy', 'Referrer-Policy is not set (optional).');
      if (/\d/.test(String(hd.server || ''))) add('info', 'server_version_disclosed', `Server header discloses a version (${String(hd.server).slice(0, 60)}).`);
    }
  }
  if (o.checkRedirect && o.http) {
    if (o.http.error) add('info', 'http_port_unreachable', `Port 80 not reachable (${o.http.error}).`);
    else if (!o.http.redirectsToHttps) add('warning', 'no_https_redirect', `http://${o.domain}/ returns ${o.http.status} without redirecting to HTTPS.`);
  }

  const status = f.reduce((s, x) => (RANK[x.severity] > RANK[s] ? x.severity : s), 'ok');
  return {
    domain: o.domain, port: o.port, role: o.role, owner: o.owner, status,
    alert: RANK[status] >= RANK[cfg.alertMinSeverity],
    daysRemaining,
    validTo: t?.cert?.validTo || null, issuer: t?.cert?.issuer || null, protocol: t?.protocol || null,
    findings: f.sort((a, b) => RANK[b.severity] - RANK[a.severity]),
    fingerprint: `${o.domain}:${o.port}|${status}|${f.filter((x) => x.severity !== 'info').map((x) => x.code).sort().join(',')}`,
  };
});

const counts = { domains: results.length, ok: 0, info: 0, warning: 0, critical: 0, alerting: 0 };
for (const r of results) { counts[r.status] += 1; if (r.alert) counts.alerting += 1; }
results.sort((a, b) => RANK[b.status] - RANK[a.status] || (a.daysRemaining ?? -1e9) - (b.daysRemaining ?? -1e9));
return [{ json: { mode, durationMs, counts, results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Alerts
// Builds every channel payload from the evaluated results:
//   slack   → one Block Kit summary per run (incoming webhook)
//   webhook → one JSON document per run
//   hubspot → one task per alerting domain (batch create)
//   notion  → one page per alerting domain
// HubSpot tasks and Notion pages are records, so they are created only when a
// domain's finding fingerprint changed or RECORD_REPEAT_DAYS have passed
// (tracked in workflow static data, production executions only). Chat and
// webhook alerts repeat every run while a problem persists.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ev = $input.first().json;
const alerts = ev.results.filter((r) => r.alert);
const ICON = { critical: '🔴', warning: '🟠', info: '🔵', ok: '🟢' };
const day = new Date().toISOString().slice(0, 10);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const top = (r, n = 3) => r.findings.filter((f) => f.severity !== 'info').slice(0, n);
const expiry = (r) => (r.daysRemaining === null ? 'cert n/a' : r.daysRemaining < 0 ? `expired ${-r.daysRemaining}d ago` : `${r.daysRemaining}d left`);

// ── record-repeat state ──
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const persist = Boolean(store) && !cfg.sandboxMode && !cfg.dryRun && cfg.executionMode === 'production';
const memory = persist ? (store.recorded = store.recorded || {}) : {};
const recordable = alerts.filter((r) => {
  const prev = memory[`${r.domain}:${r.port}`];
  return !prev || prev.fingerprint !== r.fingerprint || Date.now() - prev.at > cfg.recordRepeatDays * 86400000;
});
if (persist) {
  for (const r of recordable) memory[`${r.domain}:${r.port}`] = { fingerprint: r.fingerprint, at: Date.now() };
  for (const r of ev.results.filter((x) => !x.alert)) delete memory[`${r.domain}:${r.port}`];
}

// ── Slack ──
const head = alerts.length
  ? `${ICON.critical} ${ev.counts.critical} critical · ${ICON.warning} ${ev.counts.warning} warning · ${ev.counts.domains} domains checked`
  : `${ICON.ok} All ${ev.counts.domains} sender domains passed (threshold ${cfg.daysWarningThreshold} days)`;
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Sender domain TLS watchdog · ${day}`, emoji: true } },
  { type: 'section', text: { type: 'mrkdwn', text: head } },
];
for (const r of alerts.slice(0, 20)) {
  const lines = top(r).map((f) => `• ${esc(f.message)}`).join('\n');
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${ICON[r.status]} *${esc(r.domain)}${r.port === 443 ? '' : `:${r.port}`}* · ${esc(r.role)} · ${expiry(r)}${r.owner ? ` · owner \`${esc(r.owner)}\`` : ''}\n${lines}`.slice(0, 2900) } });
}
if (alerts.length > 20) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `…and ${alerts.length - 20} more. See the n8n execution.` }] });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `n8n run ${cfg.runId} · ${ev.mode === 'mock' ? 'SANDBOX (synthetic data)' : 'live inspection'}` }] });
const slackBody = { text: head, blocks };

// ── Webhook ──
const webhookBody = {
  event: alerts.length ? 'sender_domain_security.alert' : 'sender_domain_security.all_clear',
  generatedAt: new Date().toISOString(), runId: cfg.runId, mode: ev.mode,
  thresholds: { warningDays: cfg.daysWarningThreshold, criticalDays: cfg.criticalDays, alertMinSeverity: cfg.alertMinSeverity },
  counts: ev.counts,
  alerts: alerts.map((r) => ({ domain: r.domain, port: r.port, role: r.role, owner: r.owner, status: r.status, daysRemaining: r.daysRemaining, validTo: r.validTo, issuer: r.issuer, protocol: r.protocol, findings: r.findings })),
};

// ── HubSpot tasks ──
const due = (r) => {
  const ms = r.status === 'critical' ? 0 : Math.max(0, (r.daysRemaining ?? cfg.daysWarningThreshold) - cfg.criticalDays) * 86400000;
  return new Date(Date.now() + Math.min(ms, 7 * 86400000)).toISOString();
};
const hubspotTasks = recordable.slice(0, 100).map((r) => ({
  properties: {
    hs_task_subject: `[${r.status.toUpperCase()}] TLS/security: ${r.domain}${r.port === 443 ? '' : `:${r.port}`} (${expiry(r)})`.slice(0, 250),
    hs_task_body: `<p><strong>${esc(r.domain)}</strong> · ${esc(r.role)}${r.owner ? ` · owner ${esc(r.owner)}` : ''}</p><ul>${r.findings.map((f) => `<li>[${f.severity}] ${esc(f.message)}</li>`).join('')}</ul><p>Valid to: ${esc(r.validTo || 'n/a')} · Issuer: ${esc(r.issuer || 'n/a')} · Protocol: ${esc(r.protocol || 'n/a')}</p><p>Logged by n8n run ${esc(cfg.runId)}.</p>`,
    hs_task_status: 'NOT_STARTED',
    hs_task_priority: r.status === 'critical' ? 'HIGH' : 'MEDIUM',
    hs_task_type: 'TODO',
    hs_timestamp: due(r),
    ...(cfg.hubspotTaskOwnerId ? { hubspot_owner_id: cfg.hubspotTaskOwnerId } : {}),
  },
}));

// ── Notion pages ──
const rt = (s) => [{ type: 'text', text: { content: String(s ?? '').slice(0, 1900) } }];
const notionPages = recordable.slice(0, 50).map((r) => ({
  parent: { database_id: cfg.notionDatabaseId },
  properties: { [cfg.notionTitleProperty]: { title: rt(`${ICON[r.status]} ${r.domain}${r.port === 443 ? '' : `:${r.port}`} · ${r.status} · ${expiry(r)} · ${day}`) } },
  children: [
    { object: 'block', type: 'callout', callout: { rich_text: rt(`${r.status.toUpperCase()} · role ${r.role}${r.owner ? ` · owner ${r.owner}` : ''}`), icon: { type: 'emoji', emoji: r.status === 'critical' ? '🚨' : '⚠️' } } },
    { object: 'block', type: 'heading_2', heading_2: { rich_text: rt('Findings') } },
    ...r.findings.slice(0, 40).map((f) => ({ object: 'block', type: 'to_do', to_do: { rich_text: rt(`[${f.severity}] ${f.message}`), checked: false } })),
    { object: 'block', type: 'heading_2', heading_2: { rich_text: rt('Certificate') } },
    { object: 'block', type: 'paragraph', paragraph: { rich_text: rt(`Valid to: ${r.validTo || 'n/a'} · Issuer: ${r.issuer || 'n/a'} · Protocol: ${r.protocol || 'n/a'} · Run ${cfg.runId}`) } },
  ],
}));

return [{ json: {
  alertCount: alerts.length, counts: ev.counts, mode: ev.mode,
  slackBody, webhookBody, hubspotTasks, notionPages,
  recordable: recordable.map((r) => r.domain), suppressedRecords: alerts.length - recordable.length,
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path: domains checked, per-domain status and finding
// codes, and what each channel did. Contains no secrets and no endpoint URLs.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const all = (n) => { try { return $(n).all().map((i) => i.json); } catch (e) { return []; } };
const ran = (n) => all(n).length > 0;
const ok = (n) => all(n).filter((x) => !x.error).length;

const list = one('Load & Normalize Domain List') || {};
const ev = one('Evaluate Findings');
const cmp = one('Compose Alerts');
const channels = {
  slack: ran('Slack: Post Alert') ? (ok('Slack: Post Alert') ? 'sent' : 'failed') : ran('Slack: Post All-Clear') ? (ok('Slack: Post All-Clear') ? 'all_clear_sent' : 'failed') : 'not_sent',
  webhook: ran('Webhook: Post Alert') ? (ok('Webhook: Post Alert') ? 'sent' : 'failed') : 'not_sent',
  hubspot: ran('HubSpot: Create Tasks') ? (ok('HubSpot: Create Tasks') ? `created ${all('HubSpot: Create Tasks').reduce((n, x) => n + (Array.isArray(x.results) ? x.results.length : 0), 0)}` : 'failed') : 'not_sent',
  notion: ran('Notion: Create Incident Page') ? `created ${ok('Notion: Create Incident Page')} of ${all('Notion: Create Incident Page').length}` : 'not_sent',
};

let outcome = 'completed';
if (!list.count) outcome = 'no_domains';
else if (!ev) outcome = 'inspection_not_run';
else if (!ev.counts.alerting) outcome = 'all_clear';
else if (cfg.sandboxMode) outcome = 'alerts_found_sandbox';
else if (cfg.dryRun) outcome = 'alerts_found_dry_run';
else if (Object.values(channels).some((s) => s === 'failed')) outcome = 'alerts_found_delivery_failed';
else if (Object.values(channels).every((s) => s === 'not_sent')) outcome = 'alerts_found_no_channel_configured';
else outcome = 'alerts_found_notified';

return [{ json: {
  workflow: 'n8n-outbound-sender-domain-ssl-expiry-watchdog',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, channels: cfg.alertChannels, allowPrivateTargets: cfg.allowPrivateTargets },
  thresholds: { warningDays: cfg.daysWarningThreshold, criticalDays: cfg.criticalDays, alertMinSeverity: cfg.alertMinSeverity, headerSeverity: cfg.headerSeverity },
  domainList: { source: list.source || null, checked: list.count || 0, rejected: list.rejected || [] },
  inspection: ev ? { mode: ev.mode, durationMs: ev.durationMs, counts: ev.counts } : null,
  domains: ev ? ev.results.map((r) => ({ domain: r.domain, port: r.port, status: r.status, alert: r.alert, daysRemaining: r.daysRemaining, findings: r.findings.map((f) => `${f.severity}:${f.code}`) })) : [],
  notifications: { ...channels, recordsSuppressedByRepeatWindow: cmp ? cmp.suppressedRecords : 0 },
} }];
